#include "PluginEditor.h"
#include "BinaryData.h"         // the fonts, generated by juce_add_binary_data in CMakeLists.txt

namespace
{
    // The brand plan's shared colours, used across the whole plugin family, plus this plugin's
    // accent. Amber means one thing only: approaching the limit. -> documentation/editor-gui.md section 13
    namespace tokens
    {
        const juce::Colour base    { 0xff121417 };     // the background
        const juce::Colour surface { 0xff1b1e22 };     // raised things: the value box while typing
        const juce::Colour line    { 0xff2a2e34 };     // the ring's track
        const juce::Colour text    { 0xffe8eaed };     // the value
        const juce::Colour muted   { 0xff8a9099 };     // the name, the caption and the lockup
        const juce::Colour apricot { 0xfff2a766 };     // Simply Gain's accent, used by no paid plugin
        const juce::Colour amber   { 0xffff8a1f };     // Volcanic Amber
    }

    constexpr int defaultWidth  = 480;          // the family's smallest window, and 3:2 like its mock-ups
    constexpr int defaultHeight = 320;

    // The knob, as fractions of the ring's radius, so it scales with the window.
    // -> documentation/editor-gui.md section 13
    constexpr float ringThickness = 0.05f;      // 2.5% of the diameter
    constexpr float amberKnee     = 0.85f;      // past 85% of the range the arc turns amber

    const juce::String brandLine { " // maxximum displacement" };

    juce::Typeface::Ptr loadFont (const char* data, const int size)
    {
        return juce::Typeface::createSystemTypefaceFor (data, static_cast<size_t> (size));
    }
}


//==============================================================================
SimpleGainLookAndFeel::SimpleGainLookAndFeel()
    : inter (loadFont (BinaryData::InterRegular_ttf, BinaryData::InterRegular_ttfSize)),
      jetBrainsMono (loadFont (BinaryData::JetBrainsMonoRegular_ttf, BinaryData::JetBrainsMonoRegular_ttfSize))
{
}

juce::FontOptions SimpleGainLookAndFeel::textFont (const float height) const
{
    return juce::FontOptions (inter).withHeight (height);
}

juce::FontOptions SimpleGainLookAndFeel::monoFont (const float height) const
{
    return juce::FontOptions (jetBrainsMono).withHeight (height);
}

float SimpleGainLookAndFeel::ringRadius (const juce::Rectangle<float> knobArea)
{
    return 0.45f * juce::jmin (knobArea.getWidth(), knobArea.getHeight());
}

juce::Font SimpleGainLookAndFeel::getLabelFont (juce::Label& label)
{
    // Only the knob's value box: a fixed share of the box's height, so it scales and always fits.
    // -> documentation/editor-gui.md section 9
    if (dynamic_cast<juce::Slider*> (label.getParentComponent()) != nullptr)
        return textFont (static_cast<float> (label.getHeight()) * 0.68f);

    return LookAndFeel_V4::getLabelFont (label);
}

juce::Label* SimpleGainLookAndFeel::createSliderTextBox (juce::Slider& slider)
{
    auto* box = LookAndFeel_V4::createSliderTextBox (slider);

    // The box sits on the knob, so it lets clicks through: dragging the number turns the knob.
    // Its text editor (a child) still takes clicks while typing. -> documentation/editor-gui.md section 10
    box->setInterceptsMouseClicks (false, true);
    box->setColour (juce::TextEditor::backgroundColourId, tokens::surface);
    box->setColour (juce::TextEditor::focusedOutlineColourId, tokens::line);
    box->setColour (juce::CaretComponent::caretColourId, tokens::apricot);
    return box;
}

juce::Slider::SliderLayout SimpleGainLookAndFeel::getSliderLayout (juce::Slider& slider)
{
    // Everything that needs the knob's position asks here: drawing, dragging and the tests.
    juce::Slider::SliderLayout layout;
    layout.sliderBounds = slider.getLocalBounds();

    const auto radius = ringRadius (layout.sliderBounds.toFloat());
    const auto centre = layout.sliderBounds.getCentre().toFloat();
    layout.textBoxBounds = juce::Rectangle<float> (radius * 1.4f, radius * 0.44f)
                               .withCentre (centre.translated (0.0f, -0.04f * radius))
                               .toNearestInt();
    return layout;
}

void SimpleGainLookAndFeel::drawRotarySlider (juce::Graphics& g, const int x, const int y, const int width, const int height,
                                              const float sliderPosProportional, const float startAngle, const float endAngle,
                                              juce::Slider& slider)
{
    // Flat: a track, an arc on top of it, and a caption. No face, ticks, glow or thumb dot.
    // -> documentation/editor-gui.md section 13
    const auto bounds = juce::Rectangle<int> (x, y, width, height).toFloat();
    const auto centre = bounds.getCentre();
    const auto radius = ringRadius (bounds);
    const auto valueAngle = startAngle + sliderPosProportional * (endAngle - startAngle);    // JUCE passes 0 to 1, not an angle
    const auto stroke = juce::PathStrokeType (radius * ringThickness, juce::PathStrokeType::curved, juce::PathStrokeType::rounded);

    juce::Path track;                                           // start to end, leaving the gap at the bottom
    track.addCentredArc (centre.x, centre.y, radius, radius, 0.0f, startAngle, endAngle, true);
    g.setColour (tokens::line);
    g.strokePath (track, stroke);

    if (sliderPosProportional > 0.0f)
    {
        // The arc as a filled outline, so it can be painted twice: apricot, then amber past the knee.
        juce::Path arc, outline;
        arc.addCentredArc (centre.x, centre.y, radius, radius, 0.0f, startAngle, valueAngle, true);
        stroke.createStrokedPath (outline, arc);
        g.setColour (tokens::apricot);
        g.fillPath (outline);

        const auto kneeAngle = startAngle + amberKnee * (endAngle - startAngle);
        if (valueAngle > kneeAngle)
        {
            // A pie slice from the knee onwards (a little past the end, to cover the rounded cap).
            juce::Path pastTheKnee;
            pastTheKnee.addPieSegment (bounds.expanded (radius), kneeAngle, endAngle + 0.5f, 0.0f);

            const juce::Graphics::ScopedSaveState state (g);   // undoes the clip when it goes out of scope
            g.reduceClipRegion (pastTheKnee);
            g.setColour (tokens::amber);
            g.fillPath (outline);
        }
    }

    // The caption, small and muted, under the value.
    g.setColour (tokens::muted);
    g.setFont (monoFont (radius * 0.1f).withKerningFactor (0.25f));
    g.drawText (slider.getTitle().toUpperCase(),
                juce::Rectangle<float> (radius * 1.2f, radius * 0.15f).withCentre (centre.translated (0.0f, radius * 0.32f)),
                juce::Justification::centred);
}

void SimpleGainLookAndFeel::drawCornerResizer (juce::Graphics& g, const int width, const int height,
                                               const bool isMouseOver, const bool isMouseDragging)
{
    // Three short diagonals in the track's colour, brightening while the mouse is on them.
    g.setColour (isMouseOver || isMouseDragging ? tokens::muted : tokens::line);
    const auto w = static_cast<float> (width), h = static_cast<float> (height);

    for (const auto i : { 0.25f, 0.5f, 0.75f })
        g.drawLine (w * i, h, w, h * i, juce::jmin (w, h) * 0.075f);
}


//==============================================================================
RelativeRotarySlider::RelativeRotarySlider()
{
    setSliderStyle (Slider::Rotary);      // circular dragging; the class makes it relative

    // From about 7 o'clock round to 5, leaving a gap at the bottom. JUCE counts clockwise from 12 o'clock.
    setRotaryParameters (juce::MathConstants<float>::pi * 1.2f, juce::MathConstants<float>::pi * 2.8f, true);

    onNumberClicked = [this] { showTextBox(); };
}

void RelativeRotarySlider::mouseDown (const juce::MouseEvent& e)
{
    lastPointerAngle.reset();                   // a new grab: measure afresh
    numberDrag.reset();

    if (isOnTheNumber (e.position) && ! e.mods.isPopupMenu())
        numberDrag = NumberDrag { getValue(), e.position.y };

    Slider::mouseDown (turnedToTheDot (e));     // starts the host's gesture either way
}

void RelativeRotarySlider::mouseDrag (const juce::MouseEvent& e)
{
    if (numberDrag.has_value())
    {
        // A fine slider: up is louder, sideways is ignored, and a pixel is the same at any window size.
        // From where the drag began, so past an end it waits there. -> documentation/editor-gui.md section 10
        setValue (numberDrag->startValue + (numberDrag->startY - e.position.y) * numberDbPerPixel, juce::sendNotificationSync);
        return;
    }

    Slider::mouseDrag (turnedToTheDot (e));
}

void RelativeRotarySlider::mouseUp (const juce::MouseEvent& e)
{
    Slider::mouseUp (e);

    // The number lets clicks through to the knob, so a plain click on it opens it for typing here.
    // -> documentation/editor-gui.md section 10
    if (! e.mouseWasDraggedSinceMouseDown() && isOnTheNumber (e.position) && onNumberClicked != nullptr)
        onNumberClicked();

    numberDrag.reset();
}

void RelativeRotarySlider::mouseMove (const juce::MouseEvent& e)
{
    Slider::mouseMove (e);
    setMouseCursor (isOnTheNumber (e.position) ? juce::MouseCursor::UpDownResizeCursor : juce::MouseCursor::NormalCursor);
}

bool RelativeRotarySlider::isOnTheNumber (const juce::Point<float> position)
{
    return getLookAndFeel().getSliderLayout (*this).textBoxBounds.toFloat().contains (position);
}

juce::MouseEvent RelativeRotarySlider::turnedToTheDot (const juce::MouseEvent& e)
{
    // JUCE measures angles from the knob's centre: 0 at 12 o'clock, clockwise, in radians.
    // -> documentation/editor-gui.md section 10
    const auto centre = getLookAndFeel().getSliderLayout (*this).sliderBounds.getCentre().toFloat();
    const auto fromCentre = e.position - centre;
    const auto distance = fromCentre.getDistanceFromOrigin();

    if (distance <= 5.0f)                       // too close to have an angle; JUCE ignores it too
        return e;

    const auto pointerAngle = std::atan2 (static_cast<double> (fromCentre.x), static_cast<double> (-fromCentre.y));
    const auto rotary = getRotaryParameters();

    if (! lastPointerAngle.has_value())         // the grab starts where the value already is: no jump
        dotAngleUnlimited = rotary.startAngleRadians
                          + (rotary.endAngleRadians - rotary.startAngleRadians) * valueToProportionOfLength (getValue());
    else                                        // turn by however far the pointer turned, the short way round
        dotAngleUnlimited += std::remainder (pointerAngle - *lastPointerAngle, juce::MathConstants<double>::twoPi);

    lastPointerAngle = pointerAngle;

    // Past an end the value waits there until the pointer comes back, like a real knob's end stop.
    const auto angle = juce::jlimit (static_cast<double> (rotary.startAngleRadians),
                                     static_cast<double> (rotary.endAngleRadians), dotAngleUnlimited);
    return e.withNewPosition (centre + juce::Point { distance * static_cast<float> (std::sin (angle)),
                                                           -distance * static_cast<float> (std::cos (angle)) });
}


//==============================================================================
SimpleGainAudioProcessorEditor::SimpleGainAudioProcessorEditor (SimpleGainAudioProcessor& p)
    : AudioProcessorEditor (&p),      // the base class wants a POINTER, so we pass &p
      // The slider is declared above this, so it already exists: safe to connect.
      // -> documentation/editor-gui.md section 4
      gainAttachment (p.apvts, "gain", gainSlider)
{
    // The product name in capitals, from PRODUCT_NAME in CMakeLists.txt. -> documentation/editor-gui.md section 3
    titleLabel.setText (p.getName().toUpperCase(), juce::dontSendNotification);
    titleLabel.setJustificationType (juce::Justification::centred);
    titleLabel.setColour (juce::Label::textColourId, tokens::muted);
    addAndMakeVisible (titleLabel);

    // A rotary knob with an editable value in the middle. The ID lets the tests find it.
    // -> documentation/editor-gui.md section 3
    gainSlider.setComponentID ("gainSlider");
    gainSlider.setTitle ("Gain");                       // the caption, and what a screen reader announces
    gainSlider.setTextBoxStyle (juce::Slider::TextBoxBelow, false, 0, 0);    // getSliderLayout() places it
    gainSlider.setColour (juce::Slider::textBoxTextColourId,         tokens::text);
    gainSlider.setColour (juce::Slider::textBoxOutlineColourId,      juce::Colours::transparentBlack);
    gainSlider.setColour (juce::Slider::textBoxBackgroundColourId,   juce::Colours::transparentBlack);
    gainSlider.setColour (juce::Slider::textBoxHighlightColourId,    tokens::apricot.withAlpha (0.35f));
    addAndMakeVisible (gainSlider);

    // AFTER adding the children: they rebuild their parts with it, like the knob's value box.
    // Must be undone in the destructor. -> documentation/editor-gui.md section 9
    setLookAndFeel (&lookAndFeel);

    // Resizable by the host or by dragging the corner, from 100% to 200%,
    // always keeping the 3:2 shape. -> documentation/editor-gui.md section 8
    setResizable (true, true);
    setResizeLimits (defaultWidth, defaultHeight, defaultWidth * 2, defaultHeight * 2);
    getConstrainer()->setFixedAspectRatio (static_cast<double> (defaultWidth) / defaultHeight);
    setSize (defaultWidth, defaultHeight);
}

SimpleGainAudioProcessorEditor::~SimpleGainAudioProcessorEditor()
{
    setLookAndFeel (nullptr);           // children are still alive, so detach before they go
}


//==============================================================================
void SimpleGainAudioProcessorEditor::paint (juce::Graphics& g)
{
    // A flat background, and the lockup along the bottom left. -> documentation/editor-gui.md section 6
    g.fillAll (tokens::base);

    const auto height = static_cast<float> (getHeight());
    const auto margin = height * 0.06f;
    g.setColour (tokens::muted);
    g.setFont (lookAndFeel.monoFont (height * 0.035f));
    g.drawText (titleLabel.getText() + brandLine,
                juce::Rectangle<float> (margin, height * 0.86f, static_cast<float> (getWidth()) - margin * 2.0f, height * 0.1f),
                juce::Justification::centredLeft);
}

void SimpleGainAudioProcessorEditor::resized()
{
    // Everything is a fraction of the window's height, so it scales when resized.
    // -> documentation/editor-gui.md section 7
    const auto height = static_cast<float> (getHeight());

    titleLabel.setFont (lookAndFeel.monoFont (height * 0.045f).withKerningFactor (0.2f));
    titleLabel.setBounds (juce::Rectangle<float> (0.0f, height * 0.05f, static_cast<float> (getWidth()), height * 0.1f).toNearestInt());

    const auto knobSize = height * 0.64f;
    gainSlider.setBounds (juce::Rectangle<float> (knobSize, knobSize).withCentre (getLocalBounds().getCentre().toFloat()).toNearestInt());
}
